import { NextRequest, NextResponse } from 'next/server'
import { getSession } from '@/lib/session'
import { getAssignments, getAssignmentsWithDates, getStuffIveAssigned } from '@/lib/basecamp'

export async function GET(req: NextRequest) {
  const session = await getSession()
  if (!session.token || !session.activeAccountId) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const tab = new URL(req.url).searchParams.get('tab') || 'all'
  const accountId = session.activeAccountId
  const token = session.token.access_token

  try {
    let todos
    if (tab === 'dates') {
      todos = await getAssignmentsWithDates(accountId, token)
    } else if (tab === 'assigned') {
      todos = await getStuffIveAssigned(accountId, token)
    } else {
      todos = await getAssignments(accountId, token)
    }
    return NextResponse.json({ todos })
  } catch {
    return NextResponse.json({ error: 'Failed to fetch' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { exchangeCode, getIdentityAndAccounts } from '@/lib/basecamp'
import { getSession } from '@/lib/session'

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url)
  const code = searchParams.get('code')
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000'

  if (!code) {
    return NextResponse.redirect(`${appUrl}/?error=no_code`)
  }

  try {
    const token = await exchangeCode(code)
    const { identity, accounts } = await getIdentityAndAccounts(token.access_token)

    const session = await getSession()
    session.token = token
    session.identity = identity
    session.accounts = accounts
    session.activeAccountId = accounts[0]?.id
    await session.save()

    return NextResponse.redirect(`${appUrl}/assignments`)
  } catch {
    return NextResponse.redirect(`${appUrl}/?error=auth_failed`)
  }
}

import { getIronSession, IronSession } from 'iron-session'
import { cookies } from 'next/headers'
import { BasecampToken, BasecampIdentity, BasecampAccount } from './types'

export interface SessionData {
  token?: BasecampToken
  identity?: BasecampIdentity
  accounts?: BasecampAccount[]
  activeAccountId?: number
}

const sessionOptions = {
  password: process.env.SESSION_SECRET as string,
  cookieName: 'bc_assignments_session',
  cookieOptions: {
    secure: process.env.NODE_ENV === 'production',
    maxAge: 60 * 60 * 24 * 7, // 7 days
  },
}

export async function getSession(): Promise<IronSession<SessionData>> {
  const cookieStore = await cookies()
  return getIronSession<SessionData>(cookieStore, sessionOptions)
}

export interface BasecampToken {
  access_token: string
  refresh_token: string
  expires_at: number
}

export interface BasecampIdentity {
  id: number
  name: string
  email_address: string
  avatar_url?: string
}

export interface BasecampAccount {
  id: number
  name: string
  href: string
}

export interface TodoAssignee {
  id: number
  name: string
  avatar_url: string
}

export interface TodoParent {
  id: number
  title: string
  type: string
  app_url: string
}

export interface TodoBucket {
  id: number
  name: string
  type: string
}

export interface Todo {
  id: number
  title: string
  content: string
  due_on: string | null
  completed: boolean
  assignees: TodoAssignee[]
  parent: TodoParent
  bucket: TodoBucket
  app_url: string
  type: string
}

export interface GroupedAssignments {
  overdue: Todo[]
  today: Todo[]
  upcoming: { [date: string]: Todo[] }
  nodates: Todo[]
}

export type BulkAction = 'due_date' | 'complete'

